from AlgorithmImports import *
from datetime import timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.pending_signal = False
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.time_stop_submitted = False
        self.expiration_liquidation_submitted = False

    def OnFiveMinuteBar(self, sender, bar):
        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if (
            previous_fast is not None
            and previous_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        ):
            end_time = bar.EndTime.time()
            if time(9, 45) <= end_time <= time(14, 30):
                self.pending_signal = True

    def OnData(self, slice):
        self.HandleUnexpectedEquityPosition()

        if self.held_option is not None:
            self.ProcessHeldOption(slice)

        if self.IsExpirationProcessing():
            self.LiquidateAtExpirationProcessing()

        if self.pending_signal:
            self.pending_signal = False
            self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.held_option is not None:
            return

        if self.entry_ticket is not None and not self.IsTerminal(self.entry_ticket.Status):
            return

        chain = slice.OptionChains.get(self.spy_option.Symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiry = expirations[0]
        calls = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike > 0
        ]

        if not calls:
            self.Debug("Skipped entry: no eligible call contract at selected expiration.")
            return

        underlying_price = self.Securities[self.spy].Price
        if underlying_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        selected = min(
            calls,
            key=lambda contract: (
                abs(contract.Strike - underlying_price),
                contract.Strike
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol.Value}, "
            f"expiry={selected.Expiry.date()}, strike={selected.Strike}"
        )

    def ProcessHeldOption(self, slice):
        if self.held_option is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested:
            return

        expiry_date = self.held_option.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            self.LiquidateHeldOption("expiration processing")
            return

        if (
            current_date == expiry_date - timedelta(days=1)
            and self.Time.time() >= time(15, 45)
            and not self.time_stop_submitted
        ):
            self.LiquidateHeldOption("time stop")
            self.time_stop_submitted = True
            return

        quote = slice.Bars.get(self.held_option)
        if quote is None:
            quote = slice.QuoteBars.get(self.held_option)

        if quote is None:
            return

        bid = getattr(quote, "Bid", 0)
        ask = getattr(quote, "Ask", 0)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2
        if midpoint >= 1.5 * self.entry_price:
            self.LiquidateHeldOption("50% profit target")

    def LiquidateHeldOption(self, reason):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested:
            return

        if self.exit_ticket is not None and not self.IsTerminal(self.exit_ticket.Status):
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -holding.Quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {self.held_option.Value}, reason={reason}")

    def IsExpirationProcessing(self):
        if self.held_option is None:
            return False
        return self.Time.date() >= self.held_option.ID.Date.date()

    def LiquidateAtExpirationProcessing(self):
        if self.held_option is None or self.expiration_liquidation_submitted:
            return

        holding = self.Portfolio[self.held_option]
        if holding.Invested:
            self.LiquidateHeldOption("expiration processing")
            self.expiration_liquidation_submitted = True

    def HandleUnexpectedEquityPosition(self):
        holding = self.Portfolio[self.spy]
        if holding.Invested:
            self.Debug(
                f"Unexpected SPY equity position detected; liquidating {holding.Quantity} shares."
            )
            self.MarketOrder(self.spy, -holding.Quantity, tag="Unexpected exercise or assignment")

    def OnOrderEvent(self, order_event):
        if order_event.Status != OrderStatus.Filled:
            return

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.FillQuantity > 0:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.time_stop_submitted = False
                self.expiration_liquidation_submitted = False
                self.Debug(
                    f"Entry filled: {self.held_option.Value}, "
                    f"price={self.entry_price}"
                )

        elif self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            self.Debug(
                f"Exit filled: {order_event.Symbol.Value}, "
                f"price={order_event.FillPrice}"
            )
            if self.held_option == order_event.Symbol:
                self.held_option = None
                self.entry_price = None
                self.exit_ticket = None

    @staticmethod
    def IsTerminal(status):
        return status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.PartiallyFilled
        )

    def OnEndOfAlgorithm(self):
        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            self.LiquidateHeldOption("end of backtest")

