    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self.last_processing_date != current_date:
            self.last_processing_date = current_date
            self.expiration_stop_submitted = False
            self.no_entry_today = False

        self._handle_unexpected_spy_position()
        self._process_expiration_positions()

        if self.held_contract is not None and self.Portfolio[self.held_contract].Invested:
            self._evaluate_profit_target(slice)

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsOpen():
            self.entry_ticket = None

        spy_bar = slice.Bars[self.spy] if slice.Bars.ContainsKey(self.spy) else None
        if spy_bar is not None:
            self._update_five_minute_bar(spy_bar)

    def _update_five_minute_bar(self, minute_bar: TradeBar):
        end_local = minute_bar.EndTime.astimezone(self.TimeZone)
        local_date = end_local.date()
        local_time = end_local.time().replace(second=0, microsecond=0)

        if local_time < time(9, 35) or local_time > time(16, 0):
            return

        minute_number = local_time.hour * 60 + local_time.minute
        endpoint_number = ((minute_number - 31) // 5 + 1) * 5
        endpoint = datetime.combine(
            local_date,
            time(endpoint_number // 60, endpoint_number % 60),
            tzinfo=self.TimeZone
        )

        if self.bucket_endpoint is None:
            self.bucket_endpoint = endpoint
            self.bucket_bars = [minute_bar]
            return

        if endpoint != self.bucket_endpoint:
            self._complete_bucket()
            self.bucket_endpoint = endpoint
            self.bucket_bars = [minute_bar]
        else:
            self.bucket_bars.append(minute_bar)

    def _complete_bucket(self):
        if self.bucket_endpoint is None:
            return

        bars = self.bucket_bars
        valid = len(bars) == 5

        if valid:
            for i in range(1, len(bars)):
                previous_end = bars[i - 1].EndTime.astimezone(self.TimeZone)
                current_end = bars[i].EndTime.astimezone(self.TimeZone)
                if (current_end - previous_end) != timedelta(minutes=1):
                    valid = False
                    break

        if valid:
            close = bars[-1].Close
            self.fast_values.append(close)
            self.slow_values.append(close)

            if len(self.fast_values) >= 5 and len(self.slow_values) >= 20:
                fast = sum(list(self.fast_values)[-5:]) / 5.0
                slow = sum(self.slow_values) / 20.0

                if self.previous_fast is not None and self.previous_slow is not None:
                    bullish = (
                        self.previous_fast <= self.previous_slow
                        and fast > slow
                    )

                    endpoint_time = self.bucket_endpoint.time()
                    eligible = time(9, 45) <= endpoint_time <= time(14, 30)

                    if bullish and eligible:
                        self._try_enter()

                self.previous_fast = fast
                self.previous_slow = slow

        self.bucket_bars = []

    def _try_enter(self):
        if self.no_entry_today:
            return

        if self.held_contract is not None:
            if self.Portfolio[self.held_contract].Invested:
                return
            self.held_contract = None

        if self.entry_ticket is not None and self.entry_ticket.Status.IsOpen():
            return

        chain = self.CurrentSlice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        current_date = self.Time.date()
        eligible = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and (contract.Expiry.date() - current_date).days >= 7
        ]

        if not eligible:
            self.Debug("Skipped entry: no eligible expiration.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in eligible)

        contracts = [
            contract for contract in eligible
            if contract.Expiry.date() == selected_expiry
        ]

        if not contracts:
            self.Debug("Skipped entry: no eligible call contract.")
            return

        selected = min(
            contracts,
            key=lambda contract: (
                abs(contract.Strike - self.Securities[self.spy].Price),
                contract.Strike,
                contract.Symbol.Value
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Entry submitted: {}".format(selected.Symbol.Value))

    def _evaluate_profit_target(self, slice: Slice):
        if self.held_contract is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status.IsOpen():
            return

        quote = slice.QuoteBars[self.held_contract] \
            if slice.QuoteBars.ContainsKey(self.held_contract) else None

        if quote is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.5 * self.entry_price:
            self.exit_ticket = self.Liquidate(self.held_contract)
            self.Debug(
                "Profit target exit submitted: {} midpoint {:.2f}".format(
                    self.held_contract.Value, midpoint
                )
            )

    def _process_expiration_positions(self):
        if self.held_contract is None:
            return

        invested = self.Portfolio[self.held_contract].Invested
        if not invested:
            return

        expiry_date = self.held_contract.ID.Date.date()
        today = self.Time.date()

        if today >= expiry_date:
            self.no_entry_today = True
            if self.exit_ticket is None or not self.exit_ticket.Status.IsOpen():
                self.exit_ticket = self.Liquidate(self.held_contract)
                self.Debug("Expiration protection exit submitted.")
            return

        if self._is_trading_day_before_expiration(today, expiry_date):
            if self.Time.time() >= time(15, 45):
                if self.exit_ticket is None or not self.exit_ticket.Status.IsOpen():
                    self.exit_ticket = self.Liquidate(self.held_contract)
                    self.expiration_stop_submitted = True
                    self.Debug("Expiration time-stop exit submitted.")

    def _is_trading_day_before_expiration(self, today, expiry_date):
        day = expiry_date - timedelta(days=1)
        while day.weekday() >= 5:
            day -= timedelta(days=1)
        return today == day

    def _handle_unexpected_spy_position(self):
        holding = self.Portfolio[self.spy]
        if holding.Invested:
            self.no_entry_today = True
            self.Liquidate(self.spy)
            self.Debug("Unexpected SPY exercise or assignment position liquidated.")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            return

        if self.entry_ticket is not None:
            entry_order_id = self.entry_ticket.OrderId
            if order_event.OrderId == entry_order_id:
                self.held_contract = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        order_event.Symbol.Value,
                        order_event.FillPrice
                    )
                )
                return

        if self.exit_ticket is not None:
            exit_order_id = self.exit_ticket.OrderId
            if order_event.OrderId == exit_order_id:
                self.Debug(
                    "Exit filled: {} at {:.4f}".format(
                        order_event.Symbol.Value,
                        order_event.FillPrice
                    )
                )
