                self.consolidator.Update(spy_bar)

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        if bar.Symbol != self.spy_symbol:
            return

        if not self.fast_window.IsReady:
            self.fast_window.Add(float(bar.Close))
            self.slow_window.Add(float(bar.Close))
            return

        self.fast_window.Add(float(bar.Close))
        self.slow_window.Add(float(bar.Close))

        if not (self.fast_window.IsReady and self.slow_window.IsReady):
            return

        current_fast = sum(self.fast_window) / self.fast_window.Count
        current_slow = sum(self.slow_window) / self.slow_window.Count

        previous_fast = sum(list(self.fast_window)[1:]) / (self.fast_window.Count - 1)
        previous_slow = sum(list(self.slow_window)[1:]) / (self.slow_window.Count - 1)

        bar_end = bar.EndTime
        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        bullish_cross = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if bullish_cross and eligible_time:
            self._try_enter()

    def _try_enter(self):
        if self.no_entry_today:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        if self.current_slice is None:
            return

        chain = self.current_slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        algorithm_date = self.Time.date()
        eligible = [
            contract for contract in chain
            if contract.Symbol.ID.Date.date() >= algorithm_date + timedelta(days=7)
        ]

        if not eligible:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        expiration = min(contract.Symbol.ID.Date.date() for contract in eligible)
        candidates = [
            contract for contract in eligible
            if contract.Symbol.ID.Date.date() == expiration
            and contract.Symbol.ID.OptionRight == OptionRight.Call
        ]

        if not candidates:
            self.Debug("Skipped entry: no call contract at selected expiration.")
            return

        underlying_price = self.Securities[self.spy_symbol].Price
        if underlying_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        selected = min(
            candidates,
            key=lambda contract: (
                abs(float(contract.Strike) - underlying_price),
                float(contract.Strike)
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Submitted entry: {} expiration {} strike {}".format(
                selected.Symbol.Value, expiration, selected.Strike
            )
        )

    def _evaluate_exit(self, current_time):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        security = self.Securities.get(self.held_option)
        if security is None or not security.Invested:
            return

        contract = None
        chain = self.current_slice.OptionChains.get(self.option_symbol)
        if chain is not None:
            for item in chain:
                if item.Symbol == self.held_option:
                    contract = item
                    break

        if contract is not None:
            bid = float(contract.BidPrice)
            ask = float(contract.AskPrice)
            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                if midpoint >= 1.5 * self.entry_price:
                    self._submit_exit("profit target")
                    return

        if (
            self.expiration_date is not None and
            current_time.time() >= time(15, 45) and
            current_time.date() == self._prior_trading_day(self.expiration_date)
        ):
            self._submit_exit("expiration time stop")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        for ticket in self.Transactions.GetOpenOrders(self.held_option):
            ticket.Cancel("Canceling competing exit order.")

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.held_option, -quantity, tag=reason
            )
            self.Debug("Submitted exit for {}: {}".format(self.held_option.Value, reason))

    def _handle_expiration_processing(self):
        if self.held_option is None or self.expiration_date is None:
            return

        if self.Time.date() >= self.expiration_date:
            self.no_entry_today = True
            if self.Portfolio[self.held_option].Quantity != 0:
                self._submit_exit("expiration processing")
            else:
                self.held_option = None
                self.entry_price = None
                self.expiration_date = None

    def _handle_unexpected_spy_position(self):
        if self.Portfolio[self.spy_symbol].Quantity != 0:
            self.Debug("Unexpected SPY equity position detected; liquidating.")
            self.Liquidate(self.spy_symbol, "Unexpected exercise or assignment")

    def _prior_trading_day(self, expiration_date):
        date = expiration_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours
        while not exchange_hours.IsDateOpen(date):
            date -= timedelta(days=1)
        return date

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            return

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            self.held_option = order_event.Symbol
            self.entry_price = float(order_event.FillPrice)
            self.expiration_date = order_event.Symbol.ID.Date.date()
            self.Debug(
                "Entry filled: {} at {:.4f}".format(
                    order_event.Symbol.Value, self.entry_price
                )
            )

        elif self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            self.Debug("Exit filled: {} at {:.4f}".format(
                order_event.Symbol.Value, float(order_event.FillPrice)
            ))
            self.held_option = None
            self.entry_price = None
            self.expiration_date = None
            self.exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected option exercise or assignment detected.")
            self.Liquidate(self.spy_symbol, "Unexpected exercise or assignment")
            self.no_entry_today = True

