        if len(self.fast_window) == self.fast_window.maxlen:
            fast = sum(self.fast_window) / len(self.fast_window)

        if len(self.slow_window) == self.slow_window.maxlen:
            slow = sum(self.slow_window) / len(self.slow_window)

        bullish_crossover = (
            fast is not None and
            slow is not None and
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            fast > slow
        )

