        minute_of_day = bar_time.hour * 60 + bar_time.minute

        if minute_of_day < 570 or minute_of_day >= 960:
            return False

        # Regular-session five-minute intervals end at 09:35, 09:40, etc.
        interval_end_minute = ((minute_of_day - 570) // 5 + 1) * 5 + 570
        interval_end = datetime(
            bar_time.year,
            bar_time.month,
            bar_time.day
        ) + timedelta(minutes=interval_end_minute)

        if self.bucket_end is None:
            self.bucket_end = interval_end

        if interval_end != self.bucket_end:
            bullish = self._complete_bucket()
            self.bucket_end = interval_end
            self.bucket_bars = {}
        else:
            bullish = False

        self.bucket_bars[bar_time] = bar.Close
        return bullish

    def _complete_bucket(self):
        if self.bucket_end is None:
            return False

        expected_times = [
            self.bucket_end - timedelta(minutes=i)
            for i in range(5, 0, -1)
        ]

        if any(t not in self.bucket_bars for t in expected_times):
            return False

        close = self.bucket_bars[expected_times[-1]]

        self.closes.append(float(close))
        if len(self.closes) < self.slow_period:
            return False

        fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
        slow = sum(self.closes) / self.slow_period

        bullish = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow
        return bullish

    def _try_entry(self, slice: Slice):
        if self.expiration_blocked_date == self.Time.date():
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_date = self.Time.date() + timedelta(days=7)
        expirations = sorted({
            contract.ID.Date.date()
            for contract in chain
            if contract.ID.OptionRight == OptionRight.Call
            and contract.ID.Date.date() >= minimum_date
        })

        if not expirations:
            self.Debug("Skipped entry: no qualifying expiration.")
            return

        selected_expiration = expirations[0]
        candidates = [
            contract for contract in chain
            if contract.ID.OptionRight == OptionRight.Call
            and contract.ID.Date.date() == selected_expiration
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: abs(float(contract.Strike) - float(self.Securities[self.spy_symbol].Price))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {0}, expiration {1}, strike {2}".format(
                selected.Symbol.Value,
                selected_expiration,
                selected.Strike
            )
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_option]
        if holding.Quantity <= 0:
            return

        security = slice.QuoteBars.get(self.held_option)
        if security is None:
            return

        bid = security.Bid.Close
        ask = security.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        self.Transactions.CancelOpenOrders(self.held_option)
        self.exit_ticket = self.MarketOrder(self.held_option, -quantity)
        self.Debug("Exit submitted: {0} ({1})".format(
            self.held_option.Value,
            reason
        ))

    def _is_expiration_time_stop(self, expiration):
        if self.Time.time() < time(15, 45):
            return False

        next_day = self.Time.date() + timedelta(days=1)
        while not self.Securities[self.spy_symbol].Exchange.Hours.IsDateOpen(next_day):
            next_day += timedelta(days=1)

        return next_day == expiration

    def _handle_unexpected_spy_position(self):
        spy_holding = self.Portfolio[self.spy_symbol]
        if spy_holding.Quantity != 0:
            self.Liquidate(self.spy_symbol)
            self.expiration_blocked_date = self.Time.date()
            self.Debug(
                "Unexpected SPY exercise or assignment handling: "
                "liquidated entire SPY position."
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            return

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.FillQuantity > 0:
                self.held_option = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        order_event.Symbol.Value,
                        self.entry_price
                    )
                )

        elif self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.FillQuantity < 0:
                self.Debug("Exit filled: {0} at {1}".format(
                    order_event.Symbol.Value,
                    order_event.FillPrice
                ))
                self.held_option = None
                self.entry_price = None
                self.exit_ticket = None
                self.entry_ticket = None

