        if self.Portfolio[self.spy].Invested:
            self.Debug(
                f"{self.Time}: Unexpected SPY equity position detected; liquidating."
            )
            self.Liquidate(self.spy, "Unexpected exercise or assignment")

        self.ProcessMinuteBar(slice, local_time)

        # Never intentionally hold through expiration.
        if (
            self.option_symbol is not None
            and self.Portfolio[self.option_symbol].Invested
            and self.expiration_date is not None
            and current_date >= self.expiration_date
        ):
            if self.exit_ticket is None or not self.IsOrderOpen(self.exit_ticket):
                self.Debug(
                    f"{self.Time}: Expiration processing liquidation for "
                    f"{self.option_symbol}."
                )
                self.exit_ticket = self.MarketOrder(
                    self.option_symbol,
                    -self.Portfolio[self.option_symbol].Quantity,
                    tag="Expiration liquidation",
                )
            self.pending_signal = False
            return

        # Evaluate the profit target and scheduled time stop on every minute Slice.
