        if self.spy_symbol in slice.Bars:
            self._update_five_minute_bar(slice.Bars[self.spy_symbol])

    def _update_five_minute_bar(self, minute_bar: TradeBar):
        local_end = minute_bar.EndTime.astimezone(self.TimeZone).replace(tzinfo=None)
        local_start = minute_bar.Time.astimezone(self.TimeZone).replace(tzinfo=None)

        if local_start.time() < time(9, 30) or local_start.time() >= time(16, 0):
            return

        end_minute = local_end.minute
        if end_minute % 5 != 0 or local_end.second != 0:
            return

        boundary_end = local_end.replace(second=0, microsecond=0)
        boundary_start = boundary_end - timedelta(minutes=5)

        if boundary_start.time() < time(9, 30) or boundary_end.time() > time(16, 0):
            return

        key = boundary_end
        expected_times = [
            boundary_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if key not in self.current_five_minute_bars:
            self.current_five_minute_bars[key] = {}

        bucket = self.current_five_minute_bars[key]
        bucket[local_start.replace(second=0, microsecond=0)] = minute_bar

        if not all(t in bucket for t in expected_times):
            return

        bars = [bucket[t] for t in expected_times]
        del self.current_five_minute_bars[key]

        close = bars[-1].Close
        self.fast_values.append(close)
        self.slow_values.append(close)

        if len(self.fast_values) > 20:
            self.fast_values.pop(0)
        if len(self.slow_values) > 20:
            self.slow_values.pop(0)

        if len(self.fast_values) < 20:
            return

        current_fast = sum(self.fast_values[-5:]) / 5.0
        current_slow = sum(self.slow_values[-20:]) / 20.0

        eligible_time = time(9, 45) <= boundary_end.time() <= time(14, 30)
        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if eligible_time and bullish_cross:
            self._evaluate_entry()

    def _evaluate_entry(self):
        today = self.Time.date()

        if self.expiration_blocked_date == today:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        if self.current_slice is None or not self.current_slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Skipped call selection: no option chain.")
            return

        chain = self.current_slice.OptionChains[self.option_symbol]
        min_expiry = today + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= min_expiry
        })

        if not expiries:
            self.Debug("Skipped call selection: no expiration at least 7 days away.")
            return

        selected_expiry = expiries[0]
        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike > 0
        ]

        if not candidates:
            self.Debug("Skipped call selection: no valid call at selected expiration.")
            return

        selected = sorted(candidates, key=lambda c: c.Strike)[0]
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Call entry submitted: {selected.Symbol} "
            f"expiration={selected.Expiry.date()} strike={selected.Strike}"
        )

    def _process_option_exit(self, slice: Slice, today: date, local_time: time):
        if self.held_option is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested:
            return

        security = self.Securities[self.held_option]
        expiry = self.held_option.ID.Date.date()

        time_stop = (
            today == expiry - timedelta(days=1)
            and local_time >= time(15, 45)
        )

        profit_target = False
        if slice.ContainsKey(self.held_option):
            data = slice[self.held_option]
            bid = getattr(data, "BidPrice", 0)
            ask = getattr(data, "AskPrice", 0)
            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                profit_target = midpoint >= 1.5 * self.entry_price

        if time_stop or profit_target:
            if self.exit_ticket is None or self.exit_ticket.Status.IsClosed():
                reason = "time stop" if time_stop else "profit target"
                self.exit_ticket = self.MarketOrder(
                    self.held_option, -holding.Quantity
                )
                self.Debug(f"Call exit submitted: {reason}")

    def _process_expiration_if_needed(self, today: date):
        if self.held_option is None:
            return

        expiry = self.held_option.ID.Date.date()
        if today >= expiry:
            holding = self.Portfolio[self.held_option]
            self.expiration_blocked_date = today

            if holding.Invested:
                if self.exit_ticket is None or self.exit_ticket.Status.IsClosed():
                    self.exit_ticket = self.MarketOrder(
                        self.held_option, -holding.Quantity
                    )
                    self.Debug("Expiration processing: liquidating remaining call.")
            else:
                self.held_option = None
                self.entry_price = None

    def _handle_unexpected_spy_position(self, today: date):
        holding = self.Portfolio[self.spy_symbol]
        if holding.Invested:
            self.unexpected_exercise_blocked_date = today
            self.Liquidate(self.spy_symbol)
            self.Debug("Unexpected SPY exercise or assignment position liquidated.")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            return

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.FillQuantity > 0:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"Call entry filled: {order_event.Symbol} "
                    f"price={order_event.FillPrice}"
                )
            else:
                self.entry_ticket = None

        elif self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            self.Debug(
                f"Call exit filled: {order_event.Symbol} "
                f"price={order_event.FillPrice}"
            )
            if not self.Portfolio[order_event.Symbol].Invested:
                self.held_option = None
                self.entry_price = None
                self.exit_ticket = None

        if order_event.Symbol.SecurityType == SecurityType.Equity:
            message = str(getattr(order_event, "Message", "")).lower()
            if "assign" in message or "exercis" in message:
                self.Debug("Unexpected option exercise or assignment event handled.")
                self.Liquidate(self.spy_symbol)
